<?php
function eContrato(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function moneyContrato(float $v): string { return 'R$ '.number_format($v,2,',','.'); }
function dataContrato(?string $v): string { if(!$v) return '—'; try { return (new DateTime($v))->format('d/m/Y H:i'); } catch(Throwable){ return $v; } }
$statusNomes = ['ativa'=>'Aguardando início','em_andamento'=>'Em andamento','aguardando_confirmacao'=>'Aguardando confirmação','ajustes_solicitados'=>'Ajustes solicitados','concluida'=>'Concluída','cancelada'=>'Cancelada'];
$tipo = (string)($usuario['tipo']??'');
$status = (string)($contratacao['contratacao_status']??'');
$voltar = $tipo==='cliente' ? '/cliente/projetos-contratados.php' : '/desenvolvedor/minhas-propostas.php';
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Acompanhamento - SiteMatch</title><link rel="stylesheet" href="/css/global.css"><link rel="stylesheet" href="/css/dashboard.css"><link rel="stylesheet" href="/css/functional.css"></head><body><main class="dashboard-main" style="max-width:1050px;margin:0 auto;"><p style="margin-bottom:20px;"><a href="<?= eContrato($voltar) ?>">← Voltar</a></p>
<header class="dashboard-header"><div class="dashboard-header-text"><h1><?= eContrato((string)$contratacao['projeto_titulo']) ?></h1><p>Acompanhamento da contratação #<?= (int)$contratacao['contratacao_id'] ?></p></div><span class="projeto-status"><?= eContrato($statusNomes[$status]??$status) ?></span></header>
<?php if($mensagemSucesso!==''): ?><div class="alerta-sucesso"><?= eContrato($mensagemSucesso) ?></div><?php endif; ?><?php if($mensagemErro!==''): ?><div class="alerta-erro"><?= eContrato($mensagemErro) ?></div><?php endif; ?>
<section class="dashboard-section"><div class="resumo-grid"><article class="resumo-card"><strong><?= moneyContrato((float)$contratacao['valor_final']) ?></strong><p>Valor final</p></article><article class="resumo-card"><strong><?= (int)$contratacao['prazo_final_dias'] ?> dias</strong><p>Prazo acordado</p></article><article class="resumo-card"><strong><?= $tipo==='cliente' ? eContrato((string)$contratacao['desenvolvedor_nome']) : eContrato((string)$contratacao['cliente_nome']) ?></strong><p><?= $tipo==='cliente'?'Desenvolvedor':'Cliente' ?></p></article></div></section>
<section class="dashboard-section"><h2>Condições contratadas</h2><div class="form-card"><h3>Proposta aceita</h3><p style="margin-top:8px;line-height:1.6;"><?= nl2br(eContrato((string)$contratacao['proposta_descricao'])) ?></p><h3 style="margin-top:20px;">Entregáveis</h3><p style="margin-top:8px;line-height:1.6;"><?= nl2br(eContrato((string)($contratacao['entregaveis']??'Não informado.'))) ?></p><div class="projeto-meta" style="margin-top:20px;"><span>Aceite: <strong><?= eContrato(dataContrato($contratacao['data_aceite']??null)) ?></strong></span><span>Início: <strong><?= eContrato(dataContrato($contratacao['data_inicio']??null)) ?></strong></span><span>Entrega sinalizada: <strong><?= eContrato(dataContrato($contratacao['data_entrega']??null)) ?></strong></span><span>Conclusão: <strong><?= eContrato(dataContrato($contratacao['data_conclusao']??null)) ?></strong></span></div></div></section>
<section class="dashboard-section"><h2>Ações</h2><div class="form-card"><div class="acoes-inline"><a class="botao-secundario" href="/chat.php?proposta=<?= (int)$contratacao['proposta_id'] ?>">Abrir conversa</a><?php if($tipo==='cliente'): ?><a class="botao-secundario" href="/desenvolvedor-publico.php?id=<?= (int)$contratacao['desenvolvedor_id'] ?>">Perfil do desenvolvedor</a><?php endif; ?>
<?php if($tipo==='desenvolvedor' && $status==='ativa'): ?><form method="POST" action="/contratacao-acao.php" onsubmit="return confirm('Iniciar esta contratação?');"><input type="hidden" name="contratacao_id" value="<?= (int)$contratacao['contratacao_id'] ?>"><input type="hidden" name="acao" value="iniciar"><button class="botao-principal">Iniciar projeto</button></form><?php endif; ?>
<?php if($tipo==='desenvolvedor' && $status==='em_andamento'): ?><form method="POST" action="/contratacao-acao.php" onsubmit="return confirm('Sinalizar que o projeto foi entregue ao cliente?');"><input type="hidden" name="contratacao_id" value="<?= (int)$contratacao['contratacao_id'] ?>"><input type="hidden" name="acao" value="entregar"><button class="botao-principal">Sinalizar entrega</button></form><?php endif; ?>
<?php if($tipo==='cliente' && $status==='aguardando_confirmacao'): ?><form method="POST" action="/contratacao-acao.php" onsubmit="return confirm('Confirmar a conclusão deste projeto?');"><input type="hidden" name="contratacao_id" value="<?= (int)$contratacao['contratacao_id'] ?>"><input type="hidden" name="acao" value="concluir"><button class="botao-principal">Confirmar conclusão</button></form><?php endif; ?>
</div>
<?php if($tipo==='cliente' && $status==='aguardando_confirmacao'): ?><form method="POST" action="/contratacao-acao.php" style="margin-top:22px;" onsubmit="return confirm('Enviar a solicitação de ajustes e devolver o projeto para em andamento?');"><input type="hidden" name="contratacao_id" value="<?= (int)$contratacao['contratacao_id'] ?>"><input type="hidden" name="acao" value="ajustes"><div class="form-campo"><label for="ajustes">Solicitar ajustes</label><textarea id="ajustes" name="ajustes" required placeholder="Descreva claramente o que precisa ser ajustado."></textarea></div><div class="form-acoes"><button class="botao-secundario" type="submit">Solicitar ajustes</button></div></form><?php endif; ?>
<?php if($status==='aguardando_confirmacao' && $tipo==='desenvolvedor'): ?><div class="alerta-info" style="margin-top:18px;">A entrega foi sinalizada. Aguarde a confirmação do cliente ou uma solicitação de ajustes.</div><?php endif; ?>
<?php if($status==='concluida'): ?><div class="alerta-sucesso" style="margin-top:18px;">Esta contratação foi concluída.</div><?php endif; ?></div></section>
<?php if($tipo==='cliente' && $status==='concluida'): ?><section class="dashboard-section"><h2>Avaliação do desenvolvedor</h2><?php if(!empty($contratacao['avaliacao_id'])): ?><div class="form-card"><strong>Nota: <?= (int)$contratacao['avaliacao_nota'] ?>/5</strong><p style="margin-top:8px;"><?= eContrato((string)($contratacao['avaliacao_comentario']??'')) ?></p></div><?php else: ?><form method="POST" action="/contratacao-acao.php" class="form-card"><input type="hidden" name="contratacao_id" value="<?= (int)$contratacao['contratacao_id'] ?>"><input type="hidden" name="acao" value="avaliar"><div class="form-campo"><label for="nota">Nota</label><select id="nota" name="nota" required><option value="">Selecione</option><option value="5">5 - Excelente</option><option value="4">4 - Muito bom</option><option value="3">3 - Bom</option><option value="2">2 - Regular</option><option value="1">1 - Ruim</option></select></div><div class="form-campo" style="margin-top:14px;"><label for="comentario">Comentário</label><textarea id="comentario" name="comentario" required></textarea></div><div class="form-acoes"><button class="botao-principal" type="submit">Enviar avaliação</button></div></form><?php endif; ?></section><?php endif; ?>
</main></body></html>
